create or replace function public.social_followers_count() returns table(count bigint) language sql stable security invoker set search_path='' as $$select count(*) from public.follows where followed_id=(select auth.uid())$$;create or replace function public.social_following_count() returns table(count bigint) language sql stable security invoker set search_path='' as $$select count(*) from public.follows where follower_id=(select auth.uid())$$;create or replace function public.social_friends_count() returns table(count bigint) language sql stable security invoker set search_path='' as $$select count(*) from public.friend_requests where status='accepted' and (sender_id=(select auth.uid()) or receiver_id=(select auth.uid()))$$;revoke all on function public.social_followers_count(),public.social_following_count(),public.social_friends_count() from public,anon;grant execute on function public.social_followers_count(),public.social_following_count(),public.social_friends_count() to authenticated;create or replace function public.get_public_social_profile(p_user uuid) returns setof public.social_profiles language sql stable security invoker set search_path='' as $$select * from public.social_profiles where user_id=p_user and visibility='public' and not exists(select 1 from public.social_blocks b where (b.blocker_id=(select auth.uid()) and b.blocked_id=p_user) or(b.blocker_id=p_user and b.blocked_id=(select auth.uid())))$$;revoke all on function public.get_public_social_profile(uuid) from public,anon;grant execute on function public.get_public_social_profile(uuid) to authenticated;